  input :e_valid, 1
  input :e_i, 27
  input :e_q, 27
  input :e_g, 21
  input :e_d, 6
  input :e_j, 11
  input :sig_done, 1
  input :sig_discard, 1
  input :f_mcs, 4
  input :f_ndata, 11

  output :p_valid, 1
  output :p_a, 6
  output :p_b, 6
  output :p_first, 1
  output :p_last, 1
  output :q, 5
  output :early, 8

  memory :bufa, width: 48, depth: 128, sync_read: :clk
  memory :bufb, width: 48, depth: 128, sync_read: :clk
