      b_d = a_d
      b_par = a_par
      b_t1 = {zero16[5..0], pr1[37..16]}
      b_t2 = {zero16[5..0], pr2[37..16]}
      b_t3 = {zero16[5..0], pr3[37..16]}
    end
    if b_v == 1 do
      bufa[waddr] = word
      bufb[waddr] = word
      if b_d == 51 do
        if b_par == 1 do
          rdy1 = 1
        else
          rdy0 = 1
        end
      end
    end

    # reader: s0 issues ROM reads, s1 buffer reads, then the output register
    if rbusy == 0 do
      if act == 1 and r_rdy == 1 do
        rbusy = 1
        rstep = 0
        rc = 0
        pp = 0
      end
    else
      s0v = 1
      s0ka = kA
      s0kb = kB
      s0f = if firstp == 1 and rstep == 0 do 1 else 0 end
      s0l = if nleft == 1 and rstep == pndbps - 1 do 1 else 0 end
      s0par = rpar
      rc = rc + {zero16[7..0], kA} + {zero16[7..0], kB}
      pp = if pp == pper do 0 else pp + 1 end
      if rstep == pndbps - 1 do
        rbusy = 0
        firstp = 0
        if rpar == 1 do
          rdy1 = 0
        else
          rdy0 = 0
        end
        rpar = bnot(rpar)
        nleft = nleft - 1
        if nleft == 1 do
          act = 0
        end
      else
        rstep = rstep + 1
      end
    end
    if s0v == 1 do
      s1v = 1
      s1ka = s0ka
      s1kb = s0kb
      s1f = s0f
      s1l = s0l
      s1la = roa[2..0]
      s1lb = rob[2..0]
      s1par = s0par
    end
    if s1v == 1 do
      ov = 1
      oa = if s1ka == 1 do sa else 0 end
      ob = if s1kb == 1 do sb else 0 end
      of = s1f
      ol = s1l
    end
  end
end
